CREATE DATABASE IF NOT EXISTS findit_db; USE findit_db; CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS items(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(150) NOT NULL,category VARCHAR(80) NOT NULL,location VARCHAR(180) NOT NULL,description TEXT,type ENUM("lost","found") NOT NULL,status ENUM("open","returned") DEFAULT "open",image VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE); CREATE INDEX idx_items_type ON items(type);